package com.intellij.advancedExpressionFolding.folding.util

/** Signature-only copies of the SLF4J types the field generated by Lombok's `@Slf4j` refers to. */
val SLF4J_STUBS = arrayOf(
    """
    package org.slf4j;
    public interface Logger {
        void info(String format, Object... arguments);
        void warn(String format, Object... arguments);
    }
    """,
    """
    package org.slf4j;
    public final class LoggerFactory {
        public static Logger getLogger(Class<?> clazz) { return null; }
    }
    """,
)
